// Build up to 3 free 30-min slots. Opening: Mon-Fri 8:30-17:30, Sat 9:00-13:00, closed Sun.
const req = $('Webhook').first().json.body || {};
if (!req.preferred_date) {
  return [{json:{slots:[], message:'Missing preferred_date - ask the caller for a date'}}];
}
const events = $input.all().map(i => i.json).filter(e => e && e.start && e.start.dateTime);
const busy = events.map(e => ({start:new Date(e.start.dateTime), end:new Date(e.end.dateTime)}));
const day = new Date(req.preferred_date + 'T00:00:00');
const dow = day.getDay();
if (dow === 0) return [{json:{slots:[], message:'Closed Sundays - offer another day'}}];
const openMin = dow === 6 ? 9*60 : 8*60+30;
const closeMin = dow === 6 ? 13*60 : 17*60+30;
const pref = req.preferred_time_of_day || 'any';
const pad = n => String(n).padStart(2,'0');
const weekdays = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
const months = ['January','February','March','April','May','June','July','August','September','October','November','December'];
// NOTE: '+01:00' = Irish Summer Time. Change to '+00:00' between late Oct and late Mar.
const TZ = '+01:00';
const slots = [];
for (let t = openMin; t + 30 <= closeMin; t += 30) {
  const hh = Math.floor(t/60), mm = t % 60;
  const s = new Date(req.preferred_date + 'T' + pad(hh) + ':' + pad(mm) + ':00' + TZ);
  const e = new Date(s.getTime() + 30*60000);
  if (s.getTime() < Date.now() + 60*60000) continue; // nothing less than 1h away
  if (busy.some(b => s < b.end && e > b.start)) continue; // clashes
  if (pref === 'morning' && hh >= 12) continue;
  if (pref === 'afternoon' && hh < 12) continue;
  const h12 = ((hh + 11) % 12) + 1;
  const ampm = hh < 12 ? 'in the morning' : (hh < 17 ? 'in the afternoon' : 'in the evening');
  const spoken = weekdays[day.getDay()] + ' the ' + day.getDate() + ' of ' + months[day.getMonth()] + ' at ' + h12 + (mm ? ':' + pad(mm) : " o'clock") + ' ' + ampm;
  slots.push({date: req.preferred_date, time: pad(hh) + ':' + pad(mm), spoken});
  if (slots.length === 3) break;
}
return [{json:{
  slots,
  message: slots.length ? slots.length + ' slots found' : 'No availability that day - ask for an alternative day'
}}];
